import sys
MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    mx = max(a)

    spf = list(range(mx + 1))
    for i in range(2, int(mx ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, mx + 1, i):
                if spf[j] == j:
                    spf[j] = i

    phi = list(range(mx + 1))
    for p in range(2, mx + 1):
        if spf[p] == p:
            for j in range(p, mx + 1, p):
                phi[j] -= phi[j] // p

    aggregate = [0] * (mx + 1)
    divisor_cache = {}

    def divisors(x):
        result = divisor_cache.get(x)
        if result is not None:
            return result
        factors = []
        t = x
        while t > 1:
            p = spf[t]
            exponent = 0
            while t % p == 0:
                t //= p
                exponent += 1
            factors.append((p, exponent))
        result = [1]
        for p, exponent in factors:
            old = result
            result = []
            power = 1
            for _ in range(exponent + 1):
                result.extend(d * power for d in old)
                power *= p
        divisor_cache[x] = result
        return result

    answer = 0
    weight = 1
    output = []
    for x in a:
        ds = divisors(x)
        contribution = sum(phi[d] * aggregate[d] for d in ds) % MOD
        answer = (2 * answer + contribution) % MOD
        output.append(str(answer))
        for d in ds:
            aggregate[d] += weight
            if aggregate[d] >= MOD:
                aggregate[d] -= MOD
        weight = weight * 2 % MOD

    sys.stdout.write('\n'.join(output))

if __name__ == '__main__':
    main()

