from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        groups = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            x, y = sorted((a, b))
            groups[y].append((x, i))

        active = []
        gains = [0] * len(conflictingPairs)
        base = 0

        for right in range(1, n + 1):
            for x, pair_id in groups[right]:
                heapq.heappush(active, (-x, pair_id))

            if active:
                neg_x, pair_id = heapq.heappop(active)
                largest_x = -neg_x
                second_largest_x = -active[0][0] if active else 0
                heapq.heappush(active, (neg_x, pair_id))
            else:
                largest_x = second_largest_x = 0
                pair_id = -1

            # Number of valid subarrays ending at right.
            base += right - largest_x

            # Removing the unique pair imposing the largest lower endpoint
            # relaxes the bound to the second-largest conflicting endpoint.
            if pair_id >= 0 and largest_x > second_largest_x:
                gains[pair_id] += largest_x - second_largest_x

        return base + max(gains)

