class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        groups=[[] for _ in range(n+1)]
        for i,(a,b) in enumerate(conflictingPairs):
            x,y=sorted((a,b))
            groups[y].append((x,i))
        h=[]
        gains=[0]*len(conflictingPairs)
        base=0
        for r in range(1,n+1):
            for x,i in groups[r]: heapq.heappush(h,(-x,i))
            if h:
                neg,i=heapq.heappop(h)
                top=-neg
                second=-h[0][0] if h else 0
                heapq.heappush(h,(neg,i))
            else: top=second=0; i=-1
            base += r-top+1
            if i>=0 and top>second: gains[i]+=top-second
        return base+max(gains)

