import sys
import math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    items = []
    pos = 2
    max_rate = 0
    for _ in range(n):
        a, p, b, q = data[pos:pos + 4]
        pos += 4
        items.append((a, p, b, q))
        max_rate = max(max_rate, a, b)

    def feasible(target):
        total = 0
        for a, p, b, q in items:
            g = math.gcd(a, b)
            # Enumerate a bounded number of S machines, or a bounded
            # number of T machines; one of these suffices for an optimum.
            lim_s = min(b // g - 1, target // a)
            cost = min(
                s * p + max(0, (target - a * s + b - 1) // b) * q
                for s in range(lim_s + 1)
            )
            lim_t = min(a // g - 1, target // b)
            cost = min(cost, min(
                t * q + max(0, (target - b * t + a - 1) // a) * p
                for t in range(lim_t + 1)
            ))
            total += cost
            if total > budget:
                return False
        return True

    low, high = 0, budget * max_rate + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

