from math import comb

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)
        ways = [0] * (length + 1)

        # At each 1 in s, make this bit 0; the remaining suffix is arbitrary.
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                for suffix_ones in range(remaining + 1):
                    ways[prefix_ones + suffix_ones] += comb(remaining, suffix_ones)
                prefix_ones += 1

        answer = 0
        for weight in range(1, length + 1):
            value = weight
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            # An integer with this positive popcount needs one operation to
            # reach its popcount, followed by the reductions of that value.
            if steps + 1 <= k:
                answer += ways[weight]

        return answer % MOD

