import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    N, M, Q = next(it), next(it), next(it)
    people = [(next(it), next(it)) for _ in range(M)]
    queries = [(next(it), next(it)) for _ in range(Q)]
    ans = []
    for L, R in queries:
        parent = list(range(N + 1))
        size = [1] * (N + 1)
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        for i in range(L - 1, R):
            s, t = people[i]
            a, b = find(s), find(t)
            if a != b:
                if size[a] < size[b]:
                    a, b = b, a
                parent[b] = a
                size[a] += size[b]
        adj = [[] for _ in range(N + 1)]
        indeg = [0] * (N + 1)
        bad = False
        for i in range(L - 1, R):
            s, t = people[i]
            a = find(s)
            lo, hi = sorted((s, t))
            if s < t:
                for x in range(lo + 1, hi):
                    b = find(x)
                    if a == b:
                        bad = True
                        break
                    adj[a].append(b)
                    indeg[b] += 1
            else:
                for x in range(lo + 1, hi):
                    b = find(x)
                    if a == b:
                        bad = True
                        break
                    adj[b].append(a)
                    indeg[a] += 1
            if bad:
                break
        if bad:
            ans.append('No')
            continue
        roots = [v for v in range(1, N + 1) if find(v) == v]
        q = deque(v for v in roots if indeg[v] == 0)
        seen = 0
        while q:
            v = q.popleft()
            seen += 1
            for w in adj[v]:
                indeg[w] -= 1
                if indeg[w] == 0:
                    q.append(w)
        ans.append('Yes' if seen == len(roots) else 'No')
    sys.stdout.write('\n'.join(ans))

if __name__ == '__main__':
    main()

