    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduce the adjacency matrix over GF(2).
    pivot_cols = []
    r = 0
    for c in range(n):
        q = next((i for i in range(r, n) if (rows[i] >> c) & 1), None)
        if q is None:
            continue
        rows[r], rows[q] = rows[q], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivot_cols.append(c)
        r += 1

    pivot_set = set(pivot_cols)
    free_cols = [c for c in range(n) if c not in pivot_set]
    values = [0] * n
    # Each nullspace basis vector gets its own bit in the vertex labels.
    offset = 2 if m > 0 and len(free_cols) <= 58 else 0
    for k, f in enumerate(free_cols):
        vec = 1 << f
        for i, c in enumerate(pivot_cols):
            if (rows[i] >> f) & 1:
                vec |= 1 << c
        for i in range(n):
            if (vec >> i) & 1:
                values[i] |= 1 << (k + offset)

