    if N % d != 0:
        continue
    q = N // d
    # (6y + 3d)^2 = 12q - 3d^2
    disc = 12 * q - 3 * d * d
    if disc < 0:
        continue
    s = math.isqrt(disc)
    if s * s != disc or s <= 3 * d or (s - 3 * d) % 6 != 0:
        continue
    y = (s - 3 * d) // 6
    if y > 0:
        print(y + d, y)
        break
