import sys

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Clockwise order: NE, SE, SW, NW.
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]
        sys.setrecursionlimit(10000)

        @lru_cache(None)
        def suffix(r, c, d, turned):
            # Length starting at this 0/2 cell. The next value must alternate.
            value = grid[r][c]
            if value not in (0, 2):
                return 0
            expected = 2 if value == 0 else 0
            best = 0

            dr, dc = dirs[d]
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == expected:
                best = suffix(nr, nc, d, turned)

            if not turned:
                nd = (d + 1) % 4
                dr, dc = dirs[nd]
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == expected:
                    best = max(best, suffix(nr, nc, nd, True))
            return 1 + best

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    answer = max(answer, 1)
                    for d, (dr, dc) in enumerate(dirs):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                            answer = max(answer, 1 + suffix(nr, nc, d, False))
        return answer

