from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odd = (n + 1) // 2
        even = n // 2
        unused = set(range(1, n + 1))
        ans = []
        last = None

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def ways(o, e, next_parity):
            m = o + e
            if m == 0:
                return 1
            odds_needed = (m + 1) // 2 if next_parity == 1 else m // 2
            evens_needed = m - odds_needed
            if odds_needed != o or evens_needed != e:
                return 0
            return fact[o] * fact[e]

        while unused:
            chosen = False
            for x in sorted(unused):
                p = x % 2
                if last is not None and p == last:
                    continue
                o = odd - (p == 1)
                e = even - (p == 0)
                count = ways(o, e, 1 - p)
                if k > count:
                    k -= count
                else:
                    ans.append(x)
                    unused.remove(x)
                    odd, even, last = o, e, p
                    chosen = True
                    break
            if not chosen:
                return []
        return ans

