class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        coeff = []
        for j in range(m):
            c = powers[n - 1 - j]
            if j != n - 1 - j:
                c += powers[j]
            coeff.append(c % k)

        full = (1 << k) - 1
        suffix = [0] * (m + 1)
        suffix[m] = 1  # Only residue 0 is achievable with no digits left.
        for i in range(m - 1, -1, -1):
            mask = 0
            c = coeff[i]
            previous = suffix[i + 1]
            for digit in range(10):
                shift = (digit * c) % k
                if shift == 0:
                    mask |= previous
                else:
                    # Rotate the achievable-residue bitset by shift modulo k.
                    mask |= ((previous << shift) | (previous >> (k - shift))) & full
            suffix[i] = mask

        half = []
        remainder = 0
        for i, c in enumerate(coeff):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                needed = (-remainder - digit * c) % k
                if (suffix[i + 1] >> needed) & 1:
                    half.append(str(digit))
                    remainder = (remainder + digit * c) % k
                    break

        half = ''.join(half)
        if n % 2:
            return half + half[-2::-1]
        return half + half[::-1]

