from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # next[i] is the next position to the right whose value is
        # strictly greater than nums[i]. These are the successive
        # prefix-maximum positions when scanning from i to the right.
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        prefix = [0] * (n + 1)
        for i, value in enumerate(nums):
            prefix[i + 1] = prefix[i] + value

        log = n.bit_length()
        jump = [nxt]
        # For each jump, weight is the operations needed to bring the
        # covered positions up to their preceding prefix maximum.
        weight = [[0] * n]
        for i in range(n):
            q = nxt[i]
            weight[0][i] = nums[i] * (q - i) - (prefix[q] - prefix[i])

        for _ in range(1, log):
            prev_jump = jump[-1]
            prev_weight = weight[-1]
            cur_jump = [n] * n
            cur_weight = [0] * n
            for i in range(n):
                mid = prev_jump[i]
                if mid < n:
                    cur_jump[i] = prev_jump[mid]
                    cur_weight[i] = prev_weight[i] + prev_weight[mid]
                else:
                    cur_weight[i] = prev_weight[i]
            jump.append(cur_jump)
            weight.append(cur_weight)

        def needed(left, right):
            pos = left
            total = 0
            for level in range(log - 1, -1, -1):
                nxt_pos = jump[level][pos]
                if nxt_pos <= right:
                    total += weight[level][pos]
                    pos = nxt_pos
            # The remaining suffix has nums[pos] as its running maximum.
            return total + nums[pos] * (right - pos + 1) - (prefix[right + 1] - prefix[pos])

        answer = 0
        for left in range(n):
            low, high = left, n - 1
            while low < high:
                mid = (low + high + 1) // 2
                if needed(left, mid) <= k:
                    low = mid
                else:
                    high = mid - 1
            answer += low - left + 1
        return answer

