from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, rest = p.split('*', 1)
        b, c = rest.split('*', 1)
        n = len(s)

        def occurrences(word):
            if not word:
                return list(range(n + 1))
            m = len(word)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and word[i] != word[j]:
                    j = pi[j - 1]
                if word[i] == word[j]:
                    j += 1
                pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != word[j]:
                    j = pi[j - 1]
                if ch == word[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        aa, bb, cc = occurrences(a), occurrences(b), occurrences(c)
        ans = n + 1
        la, lb, lc = len(a), len(b), len(c)
        for x in aa:
            ib = bisect_left(bb, x + la)
            if ib == len(bb):
                continue
            y = bb[ib]
            ic = bisect_left(cc, y + lb)
            if ic == len(cc):
                continue
            end = cc[ic] + lc
            if end - x < ans:
                ans = end - x
        return -1 if ans == n + 1 else ans

