def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    potential = [-1] * n
    answer = [0] * n
    for start in range(n):
        if potential[start] != -1:
            continue
        potential[start] = 0
        queue = [start]
        component = []
        for u in queue:
            component.append(u)
            for v, z in graph[u]:
                expected = potential[u] ^ z
                if potential[v] == -1:
                    potential[v] = expected
                    queue.append(v)
                elif potential[v] != expected:
                    print(-1)
                    return

        size = len(component)
        root_value = 0
        for bit in range(31):
            ones = sum((potential[u] >> bit) & 1 for u in component)
            if ones > size - ones:
                root_value |= 1 << bit
        for u in component:
            answer[u] = potential[u] ^ root_value

    print(*answer)

