    for z in range(N):
        w, v = items[2 * z], items[2 * z + 1]
        ndp = [neg] * (W + 1)
        for r in range(min(w, W + 1)):
            hull = []
            head = 0
            max_t = (W - r) // w
            for t in range(max_t + 1):
                idx = r + t * w
                val = dp[idx]
                if val != neg:
                    m = 2 * t
                    b = val - t * v - t * t
                    while len(hull) - head >= 2:
                        m1, b1 = hull[-2]
                        m2, b2 = hull[-1]
                        if (b1 - b2) * (m - m2) >= (b2 - b) * (m2 - m1):
