from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Construct the required postorder iteratively to avoid recursion limits.
        order = []
        stack = [(0, False)]
        while stack:
            v, done = stack.pop()
            if done:
                order.append(v)
            else:
                stack.append((v, True))
                for u in reversed(children[v]):
                    stack.append((u, False))

        pos = [0] * n
        for i, v in enumerate(order):
            pos[v] = i

        # Subtree sizes; each subtree forms a contiguous interval in postorder.
        sizes = [1] * n
        for v in order:
            if parent[v] != -1:
                sizes[parent[v]] += sizes[v]

        text = ''.join(s[v] for v in order)
        m = len(text)

        # Manacher radii: odd[i] includes the center; even[i] is centered at i-1/i.
        odd = [0] * m
        left = 0
        right = -1
        for i in range(m):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < m and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left = i - k + 1
                right = i + k - 1

        even = [0] * m
        left = 0
        right = -1
        for i in range(m):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < m and text[i - k - 1] == text[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left = i - k
                right = i + k - 1

        answer = []
        for v in range(n):
            end = pos[v]
            length = sizes[v]
            start = end - length + 1
            if length & 1:
                center = (start + end) // 2
                answer.append(odd[center] >= length // 2 + 1)
            else:
                center = (start + end + 1) // 2
                answer.append(even[center] >= length // 2)
        return answer

