class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Prefix indices with the same remainder modulo k delimit lengths
        # divisible by k. Keep the smallest prior prefix for each remainder.
        min_prefix = {0: 0}
        prefix = 0
        best = None

        for index, value in enumerate(nums, 1):
            prefix += value
            remainder = index % k

            if remainder in min_prefix:
                candidate = prefix - min_prefix[remainder]
                if best is None or candidate > best:
                    best = candidate

            if remainder not in min_prefix or prefix < min_prefix[remainder]:
                min_prefix[remainder] = prefix

        return best

