N = int(sys.stdin.buffer.read())
M = math.isqrt(N)

# Sieve primes up to sqrt(N).
sieve = bytearray(b'\x01') * (M + 1)
sieve[0] = 0
if M >= 1:
    sieve[1] = 0
for p in range(2, math.isqrt(M) + 1):
    if sieve[p]:
        start = p * p
        sieve[start:M + 1:p] = b'\x00' * (((M - start) // p) + 1)
primes = [p for p in range(2, M + 1) if sieve[p]]

# Numbers with exactly 9 divisors have forms p^8 or p^2 q^2 (p < q).
answer = 0
right = len(primes) - 1
for i, p in enumerate(primes):
    while right > i and p * primes[right] > M:
        right -= 1
    if right <= i:
        break
    answer += right - i

for p in primes:
    if p ** 8 <= N:
        answer += 1
    else:
        break

print(answer)

