    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n, q = map(int, data[:2])
    s = bytearray(data[2])
    out = []

    def match(i):
        return i >= 0 and i + 2 < n and s[i] == 65 and s[i + 1] == 66 and s[i + 2] == 67

    count = sum(match(i) for i in range(n - 2))
    j = 3
    for _ in range(q):
        x = int(data[j]) - 1
        c = data[j + 1][0]
        j += 2
        # Only substrings starting at x-2, x-1, or x can be affected.
        for i in (x - 2, x - 1, x):
            if match(i):
                count -= 1
        s[x] = c
        for i in (x - 2, x - 1, x):
            if match(i):
                count += 1
        out.append(str(count))

    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
