from typing import List

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        n = len(nums)
        strings = [str(x) for x in nums]
        width = max(map(len, strings))
        strings = [s.zfill(width) for s in strings]

        answer = 0
        for i in range(n):
            for j in range(i + 1, n):
                a, b = strings[i], strings[j]
                mismatches = []
                for k, (x, y) in enumerate(zip(a, b)):
                    if x != y:
                        mismatches.append(k)
                        if len(mismatches) > 2:
                            break
                if not mismatches:
                    answer += 1
                elif len(mismatches) == 2:
                    p, q = mismatches
                    if a[p] == b[q] and a[q] == b[p]:
                        answer += 1
        return answer

