        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        # prev[j] stores LCP(nums[i+1:], nums[j:]); update it for each i.
        prev = [0] * (n + 1)
        answer = 0
        for i in range(n - 2, 0, -1):
            cur = [0] * (n + 1)
            for j in range(i + 1, n):
                if nums[i] == nums[j]:
                    cur[j] = 1 + prev[j + 1]

            for j in range(i + 1, n):
                # nums1 is a prefix of nums2, requiring nums2 to be long enough;
                # or nums2 is a prefix of nums3.
                if (j - i >= i and z[i] >= i) or cur[j] >= j - i:
                    answer += 1
            prev = cur
