def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    neg = -10**30
    dp = [neg, neg]  # best sum of a nonempty surviving stack ending at each index parity
    for i, x in enumerate(a):
        p = i & 1  # zero-based parity; first item has parity 0
        if p == 0:
            dp[0] = max(dp[0], x, dp[1] + x)
        else:
            dp[1] = max(dp[1], dp[0] + x)
    ans = dp[(n - 1) & 1]
    if n % 2 == 0:
        ans = max(ans, 0)  # all operations can be paired, leaving an empty stack
    print(ans)

