class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        base = s.count('1')
        zero_runs = [(length, idx) for idx, (bit, length) in enumerate(runs) if bit == '0']
        zero_runs.sort(reverse=True)

        best_gain = 0  # No trade is always allowed.
        for i in range(1, len(runs) - 1):
            if runs[i][0] != '1':
                continue
            if runs[i - 1][0] != '0' or runs[i + 1][0] != '0':
                continue

            one_length = runs[i][1]
            # Flipping the selected 1-run joins its adjacent zero runs;
            # turning that merged run back on gains the two outer zero lengths.
            gain = runs[i - 1][1] + runs[i + 1][1]

            # Alternatively, the second flip may use any other zero run.
            for length, idx in zero_runs:
                if idx != i - 1 and idx != i + 1:
                    gain = max(gain, length - one_length)
                    break
            best_gain = max(best_gain, gain)

        return base + best_gain

