from typing import List

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        pts = {tuple(p) for p in points}
        xs = sorted({x for x, y in pts})
        ys = sorted({y for x, y in pts})
        best = -1

        for i, x1 in enumerate(xs):
            for x2 in xs[i + 1:]:
                for j, y1 in enumerate(ys):
                    for y2 in ys[j + 1:]:
                        corners = ((x1, y1), (x1, y2), (x2, y1), (x2, y2))
                        if not all(corner in pts for corner in corners):
                            continue

                        # Any other point in the closed rectangle, including on its
                        # border, makes this rectangle invalid.
                        if any(
                            x1 <= x <= x2 and y1 <= y <= y2 and (x, y) not in corners
                            for x, y in pts
                        ):
                            continue

                        best = max(best, (x2 - x1) * (y2 - y1))

        return best

